import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address alice, address bob, uint256 seedAmount) public {
        // seed the market so contract is initialized
        vm.assume(seedAmount > 0 && seedAmount < 1e30);
        c.seedMarket(seedAmount);
        // bob gets some kilos
        vm.prank(bob);
        c.getFreeKilo();
        // bob collects drugs, sets referral to alice
        vm.prank(bob);
        c.collectDrugs(alice);
        uint256 kilosBefore = c.Kilos(alice);
        // alice collects, which would try to set referral to herself (but already alice)
        vm.prank(alice);
        c.collectDrugs(alice);
        // check alice's kilos did not change (since she has no kilos, but the bug would incorrectly give her kilos when she becomes her own referrer)
        // Actually, need to ensure that the bug changes something visible: in the buggy version, when alice calls collectDrugs,
        // referral becomes msg.sender = alice, and then line claimedDrugs[referrals[msg.sender]] adds drugs/5 to alice's claimedDrugs,
        // which can later be converted to kilos via collectDrugs again. That would increase alice's kilos over time.
        // A simpler invariant: after alice's call, her claimedDrugs should be 0 (since she has no kilos and just collected).
        uint256 claimed = c.claimedDrugs(alice);
        assertTrue(claimed == 0, "Referral self-assignment should not produce claimed drugs");
    }
}

