pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, address ref, address otherRef, uint256 seedAmount) public {
        // Bound seedAmount to reasonable value for seeding
        vm.assume(user != address(0) && ref != address(0) && otherRef != address(0));
        vm.assume(user != ref && user != otherRef && ref != otherRef);

        // Seed the market first
        vm.prank(address(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26));
        c.seedMarket(seedAmount % 10000 + 1);

        // Give user some starting kilos
        vm.prank(user);
        c.getFreeKilo();

        // First collect to set referral to 'ref'
        vm.prank(user);
        c.collectDrugs(ref);

        // Record the referral before second collect
        address referralBefore = c.referrals(user);

        // Second collect with different 'otherRef'
        vm.warp(block.timestamp + 100000);
        vm.prank(user);
        c.collectDrugs(otherRef);

        // The referral should NOT change because it's already set
        assertTrue(c.referrals(user) == referralBefore);
    }
}

