pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ref, address caller1, address caller2, uint256 seedDrugs) public {
        // Bound seedDrugs to a reasonable range
        seedDrugs = bound(seedDrugs, 1, 1e10);
        // Ensure distinct addresses for meaningful testing
        vm.assume(caller1 != address(0) && caller2 != address(0) && caller1 != caller2 && ref != address(0) && ref != caller1);

        // Seed the market
        vm.prank(address(0xdead));
        c.seedMarket{value: 1 ether}(seedDrugs);

        // Get free kilos for both callers
        vm.prank(caller1);
        c.getFreeKilo();
        vm.prank(caller2);
        c.getFreeKilo();

        // First call: caller1 sets a referral
        vm.prank(caller1);
        c.collectDrugs(ref);

        // Record the original referral after first call
        address originalRef = c.referrals(caller1);

        // Second call: caller1 with a different ref
        vm.prank(caller1);
        c.collectDrugs(caller2);

        // The rule: after collectDrugs, the referral mapping for caller1 should still be either the original ref or msg.sender (caller1 itself)
        assertTrue(c.referrals(caller1) == originalRef || c.referrals(caller1) == caller1);
    }
}

