pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref, uint256 initialMarketDrugs, uint256 initialBalance) public {
        // Ensure marketDrugs is not zero so that collectDrugs can work
        vm.assume(initialMarketDrugs > 0);
        // Fund the contract and set marketDrugs via seedMarket (which also sets initialized=true)
        vm.deal(address(c), initialBalance);
        c.seedMarket(initialMarketDrugs);
        // Give the caller some kilos via getFreeKilo
        vm.prank(caller);
        c.getFreeKilo();
        // Fast forward time to accumulate drugs
        vm.warp(block.timestamp + 86401);
        // Record claimedDrugs of referral before collectDrugs
        uint256 referralBefore = c.claimedDrugs(ref);
        // Call collectDrugs from caller with ref
        vm.prank(caller);
        c.collectDrugs(ref);
        // After collectDrugs, compute expected drugsUsed: getMyDrugs() from caller
        uint256 drugsUsed = c.getMyDrugs();
        // A subsequent call to DrugDealer (changing CEO, but not affecting claimedDrugs) to trigger the mutant difference
        // But DrugDealer doesn't change claimedDrugs. So the rule must be that the referral's claimedDrugs increased by drugsUsed/5 relative to what it would be after internal reset.
        // Actually, after collectDrugs, caller's claimedDrugs is reset to 0, but referral's claimedDrugs should have added drugsUsed/5.
        // Since we cannot directly observe drugsUsed (now getMyDrugs returns 0 after reset), we compute it from kilos and time passed.
        uint256 kilos = c.getMyKilo();
        uint256 secondsPassed = block.timestamp - c.lastCollect(caller);
        uint256 expectedDrugsUsed = secondsPassed * kilos;
        // Expected referral increase = expectedDrugsUsed / 5
        uint256 expectedReferralIncrease = expectedDrugsUsed / 5;
        // After collectDrugs, referral's claimedDrugs should be referralBefore + expectedReferralIncrease
        uint256 referralAfter = c.claimedDrugs(ref);
        // The property: referralAfter equals referralBefore + expectedReferralIncrease
        assertTrue(referralAfter == referralBefore + expectedReferralIncrease, "Referral bonus mismatch");
    }
}

