        // Seed the market and get free kilo to have non-zero Kilos
        c.seedMarket{value: 1 ether}(100);
        c.getFreeKilo();
        // Record lastCollect before call
        uint256 before = c.lastCollect(address(this));
        // Call DrugDealer (this sets ceoAddress, but doesn't affect state we care about)
        c.DrugDealer();
        // The rule: after DrugDealer, the lastCollect timestamp must be >= block.timestamp
        uint256 after = c.lastCollect(address(this));
        assertTrue(after == block.timestamp);
    }
}

